    #{operParam}, #{jsonResult}, #{status}, #{errorMsg}, NOW(), #{costTime}, #{ipAddr}
)

mapper.select:
SELECT * FROM sys_operation_log
AND module LIKE CONCAT('%', #{module}, '%') AND username LIKE CONCAT('%', #{username}, '%') AND status = #{status}
ORDER BY oper_time DESC
